WITH flattened_attrs AS (SELECT id, plan, tier_limits, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT id, plan, LAG(entry_price) OVER (PARTITION BY plan ORDER BY entry_price, id) AS prev_entry_price, LAG(avg_tier_price) OVER (PARTITION BY plan ORDER BY entry_price, id) AS prev_avg_tier_price, LEAD(avg_tier_price) OVER (PARTITION BY plan ORDER BY entry_price, id) AS next_avg_tier_price, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY entry_price, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY avg_tier_price DESC, id) AS seq_no FROM flattened_attrs WHERE entry_price <= 21;
